def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'C':
            my_c += 1
        else:
            my_d += 1

    last_me, last_opp = history[-1]

    if n >= 10 and opp_d > 0.35 * n:
        return 'D'

    exploitable = False
    retaliates = False
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i+1][1] == 'D':
                retaliates = True
            elif history[i+1][1] == 'C':
                exploitable = True

    if exploitable:
        return 'D'

    remaining = 100 - n
    if remaining <= 1:
        return 'D'
    if remaining <= 5:
        if opp_d == 0:
            return 'C'
        if retaliates:
            return 'C'
        if opp_d > opp_c:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if opp_c > 0.8 * n:
            return 'C'
        def_streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                def_streak += 1
            else:
                break
        if def_streak >= 3 and opp_c > 0.6 * n:
            return 'C'
        if def_streak == 2 and opp_c > 0.7 * n:
            return 'C'
        if def_streak == 1 and opp_c > 0.7 * n:
            return 'C'
        return 'D'
    else:
        if opp_c >= opp_d:
            return 'C'
        if opp_d > 2 * opp_c:
            return 'D'
        return 'C'
